local MournPlotCell = Class('MournPlotCell')
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')

function MournPlotCell:__init()

end

function MournPlotCell:__delete()

end

function MournPlotCell:Awake()
 	CfUtils.SetActive(self.CheckpointCell.gameObject, true)
	SetButtonAction(self.ButtonNode.gameObject,Bind(self,self.OnBtnNodeClick))
end

function MournPlotCell:UpdateContent(data)
	self.data = data
	self.index   = data.index
	CfUtils.FillText(self.TxtNumber, self.index)
	
	local isFinish = ActivityMournUtils.IsUnLockPlot(self.data.id)
	CfUtils.SetActive(self.Finish.gameObject,isFinish)
	if not isFinish then
		local isUnLock = ActivityMournUtils.IsUnLockPlot(self.data.unlockPlot)
		CfUtils.SetActive(self.Lock.gameObject, not isUnLock)
	end
end

function MournPlotCell:SetLockState(state)
	CfUtils.SetActive(self.Lock.gameObject,state)
end

function MournPlotCell:SetFinishState(state)
	CfUtils.SetActive(self.Finish.gameObject,state)
end

function MournPlotCell:UpdatePosition(position)
	for _, animationState in pairs(self.CheckpointCell) do
		animationState.normalizedTime = position
		animationState.speed = 0
	end
	self.CheckpointCell:Play()
	self._position = position
end

function MournPlotCell:SetSelectState(state)
	local status = state and 2 or 1
	CfUtils.SetUISwitchImage(self.ImgBg, status)
	CfUtils.SetUISwitchText(self.TxtNumber,status)
	CfUtils.SetActive(self.ImgArrow.gameObject,state)
end

function MournPlotCell:UpdateSelectedNode()
	cs_coroutine.start(function()
		cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.15))
	end)
end

function MournPlotCell:OnBtnNodeClick()
	local isUnLock = ActivityMournUtils.IsUnLockPlot(self.data.unlockPlot)
	if not isUnLock then
		GameUtils.Toast(localize("请先通关前置关卡"))
		return
	end
	if isNotNull(self.data.callBack) then
		self.data.callBack(self.index)
	end
end

function MournPlotCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return MournPlotCell